using UnityEngine;

namespace UnityBox.AvatarSecuritySystem
{
    /// <summary>Input API for the standalone Unity controller generated by ASS.</summary>
    public sealed class StandaloneSecurityInput : MonoBehaviour
    {
        [HideInInspector] public string passwordParameter = "ASS_PasswordCorrect";
        [HideInInspector] public string timeoutParameter = "ASS_TimeUp";
        [HideInInspector] public string restartParameter = "ASS_Restart";
        private Animator animator;
        private Animator Controller => animator != null ? animator : animator = GetComponent<Animator>();

        public bool IsUnlocked => Controller.GetBool(passwordParameter);
        public bool HasTimedOut => Controller.GetBool(timeoutParameter);
        public void SetGesture(int gesture, bool rightHand = false) =>
            Controller.SetInteger(rightHand ? "GestureRight" : "GestureLeft", gesture);

        public void Restart()
        {
            Controller.SetBool(passwordParameter, false);
            Controller.SetBool(restartParameter, true);
        }
    }
}
